class Solution:
    def countCompleteSubstrings(self, word: str, k: int) -> int:
        n = len(word)
        # Split into blocks where adjacent chars differ by at most 2
        blocks = []
        start = 0
        for i in range(1, n + 1):
            if i == n or abs(ord(word[i]) - ord(word[i - 1])) > 2:
                blocks.append((start, i))
                start = i

        result = 0
        for (lo, hi) in blocks:
            length = hi - lo
            for m in range(1, 27):
                win = m * k
                if win > length:
                    break
                cnt = [0] * 26
                exact = 0  # number of characters with count exactly k
                distinct = 0
                for i in range(lo, hi):
                    c = ord(word[i]) - 97
                    # add char i
                    cnt[c] += 1
                    if cnt[c] == k:
                        exact += 1
                    elif cnt[c] == k + 1:
                        exact -= 1
                    # remove char out of window
                    j = i - win
                    if j >= lo:
                        d = ord(word[j]) - 97
                        if cnt[d] == k:
                            exact -= 1
                        elif cnt[d] == k + 1:
                            exact += 1
                        cnt[d] -= 1
                        if cnt[d] == k:
                            exact += 1
                    # check window of size win ending at i
                    if i - lo + 1 >= win:
                        # count of characters with exact count k equals m
                        # and window length is m*k, so all chars are exactly k
                        if exact == m:
                            result += 1
        return result
